mapper.select:
select
c1.C_Name as dCompanyName,
mn.*
from  SYS_Department mn
left join  SYS_Company c1 on mn.D_Company_Id=c1.C_Id
where 1=1

    and  mn.Te_Id=#{params.teId}


  and  mn.D_Status=#{params.dStatus}


    and  mn.D_Code=#{params.dCode}


    and  mn.D_Type=#{params.dType}


    and mn.d_code not in
  
      #{code}
  

order by mn.D_Sort asc
